import{_ as n,a0 as p,w as a,s as l,ao as T,I as o,x as e,a1 as i,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"為什麼計量 IT 的生產力如此具有挑戰性？ | LCTT x X-CMD","titleTemplate":false,"description":"為什麼計量 IT 的生產力如此具有挑戰性？ | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼計量 IT 的生產力如此具有挑戰性？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼計量 IT 的生產力如此具有挑戰性？ | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160808 Why measuring IT productivity is so challenging","title":"為什麼計量 IT 的生產力如此具有挑戰性？","tag":"201609","desc":""},"relativePath":"201609/20160808 Why measuring IT productivity is so challenging.md","filePath":"[post].md"}'),m={name:"201609/20160808 Why measuring IT productivity is so challenging.md"};function u(d,t,g,I,f,C){const r=p("Link");return a(),l("div",null,[t[15]||(t[15]=T('<h1 id="為什麼計量-it-的生產力如此具有挑戰性" tabindex="-1">為什麼計量 IT 的生產力如此具有挑戰性？ <a class="header-anchor" href="#為什麼計量-it-的生產力如此具有挑戰性" aria-label="Permalink to “為什麼計量 IT 的生產力如此具有挑戰性？”">​</a></h1><p><img src="https://enterprisersproject.com/sites/default/files/styles/620x350/public/images/cio_talent_6.png?itok=JV-zSor3" alt=""></p><p>在某些行業裏，人們可以根據一些測量標準判定一個人的生產力。比如，如果你是一個零件製造商，可以通過一個月你能夠製造的零件數量來確定你的生產效率。如果你在客户服務中心工作，你解答了多少個客户來電，你的平均解答時間都會成為評判你的生產效率的依據。這些都是相當簡單的案例，但即便你是一位醫生，也可以通過你主刀的臨牀手術次數或者一個月你確診的患者數量來確定你的生產效率。無論這些評判標準正確與否，但它們提供了一個通用的方法來評斷一個人在給定時間內的執行能力。</p><p>然而在 IT 這方面，通過上述方法來衡量一個人的生產力是不可能的，因為 IT 有太多的變化性。比如，通過一個開發者編寫的代碼行數來衡量開發者所用的時間看起來很誘人。但是，編程的語言很大程度上能影響到根據這種方法得到的結論。因為一種編程語言的一行代碼比用其他編程語言編寫所花費的時間和難度可能會明顯的多或少。</p><p>它總是這樣不可捉摸嗎？多年以前，你可能聽説過或者經歷過根據功能點來衡量 IT 工作人員的生產效率。這些措施是針對開發者們能夠創建的關鍵特徵來衡量開發者的生產效率的。但這種方法在今天也變得逐漸難以實施，開發者經常將可能已有的邏輯封裝進內部，比如，按供應商來整合功能點。這使得僅僅是基於功能點的數目來估量生產效率難度加大。</p><p>這兩個例子能夠闡述為什麼當我們 CIO 之間談論 IT 生產效率的時候有時會引起爭論。考慮以下這個假想中的談話：</p><blockquote><p>IT leader：“天啊，我想這些開發者一定很厲害。”<br> HR：“真的假的，他們做了什麼？”<br> IT leader：“他們做了個相當好的應用。” HR：“好吧，那他們比那些做了 10 個應用的開發者更好嗎” IT leader：“這要看你怎麼理解 ‘更好’。”</p></blockquote><p>這個對話比較有代表性。當我們處於上述的這種交談時，這裏面有太多的主觀因素導致我們很難回答這個問題。當我們用一種有意義的方法來測試 IT 的效率時，類似上述談話的這種問題僅僅是冰山一角。這不僅僅使談話更加困難－它還會使 CIO 們很難展示他們的團隊在商業上的價值。</p><p>確實這不是一個新出現的問題。我已經花費差不多 30 年的時間來思考這個問題。我得出的結論是我們真的不應該在談論 IT 的生產效率這件事上面相互煩擾－因為我們永遠不可能有結論。</p><p>我認為我們需要在改變這種對話同時停止根據生產能力和成本來談論 IT 的生產效率，將目光集中於衡量 IT 的整體商業價值上。重申一下，這個過程不會很容易。商業價值的實現是一件困難的事情。但如果 CIO 們能夠和商業人員合作來解決這個問題，就可以將實際價值變的更加科學而非一種藝術形式。</p><hr>',11)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),i(r,{href:"https://enterprisersproject.com/article/2016/8/why-measuring-it-productivity-so-challenging"},{default:s(()=>[...t[0]||(t[0]=[e("https://enterprisersproject.com/article/2016/8/why-measuring-it-productivity-so-challenging",-1)])]),_:1})]),o("p",null,[t[6]||(t[6]=e("作者：",-1)),i(r,{href:"https://enterprisersproject.com/user/anil-cheriyan"},{default:s(()=>[...t[2]||(t[2]=[e("Anil Cheriyan",-1)])]),_:1}),t[7]||(t[7]=e(" 譯者：",-1)),i(r,{href:"https://github.com/LemonDemo"},{default:s(()=>[...t[3]||(t[3]=[e("LemonDemo",-1)])]),_:1}),t[8]||(t[8]=e("　",-1)),i(r,{href:"https://github.com/WangYueScream"},{default:s(()=>[...t[4]||(t[4]=[e("WangYueScream",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),i(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=e("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),i(r,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const L=n(m,[["render",u]]);export{h as __pageData,L as default};
